+    this.compressor = null;
+    this.buses = null;
+    this.toneVoices = [];
+    this.musicVoices = [];
+    this.noiseVoices = [];
+    this.noiseSource = null;
+    this.sequences = new Map();
+    this.sequenceSerial = 0;
+    this.muted = false;
+    this.volumes = { ...DEFAULT_VOLUMES };
+    this.disposed = false;
+  }
+
+  get unlocked() {
+    return Boolean(this.context && this.context.state !== 'closed');
